import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"银行家算法","description":"","frontmatter":{"title":"银行家算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/banker-algorithm.md","filePath":"cs/banker-algorithm.md","lastUpdated":1789023840000}'),h={name:"cs/banker-algorithm.md"};function m(E,a,_,A,f,u){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="银行家算法" tabindex="-1">银行家算法 <a class="header-anchor" href="#银行家算法" aria-label="Permalink to &quot;银行家算法&quot;">​</a></h1><div class="epigraph"><p>只在分配之后仍存在安全序列时才把资源给出去；否则让请求者等待。</p><footer>—— 据 Dijkstra 对银行家算法的表述；Habermann, Prevention of System Deadlocks, CACM 1969 整理</footer></div><p><a href="/cs/deadlock-prevent">上一课</a>用四条件刻画死锁，预防常靠锁排序或一次性申请，对「先声明最大需求、再分次要」的系统太死。缺口是<strong>回避</strong>：每次分配都检查「即使所有人随后按最坏顺序要满配额，仍能找到做完的次序」。这就是银行家算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程声明最大需求向量，当前占用 + 仍可再要 ≤ 声明。系统有剩余向量。一次请求若立刻满足，剩余减少；若存在一个序列，使每个进程能在「剩余足够其仍需」时跑完并归还，则状态安全。缺口不是再列 Coffman 条件，而是这个安全检查。不安全不是已经死锁，而是存在走向死锁的路径。</p><p>本课不把多资源类型的矩阵代码写成可编译程序，只钉判据。</p><p><span class="marginnote">Dijkstra 把银行家比作：放贷后仍能应付所有客户按额度提现的某种次序。Habermann 把它接到操作系统资源管理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对剩余 \\(A\\)、仍需矩阵 \\(Need\\)：反复找尚未完成且 \\(Need_i \\le A\\) 的进程，假想它跑完，\\(A\\) 加上它当前占用。若所有进程都能这样被点到，安全。分配前对试探后的状态跑同一检查，失败则阻塞请求。</p>',9)),(e(),l(c,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20TRY%5B%22%E8%AF%95%E6%8E%A2%E5%88%86%E9%85%8D%22%5D%0A%20%20TRY%20--%3E%20SAFE%5B%22%E5%AD%98%E5%9C%A8%E5%AE%89%E5%85%A8%E5%BA%8F%E5%88%97%3F%22%5D%0A%20%20SAFE%20--%3E%20YES%5B%22%E7%9C%9F%E6%AD%A3%E7%BB%99%E8%B5%84%E6%BA%90%22%5D%0A%20%20SAFE%20--%3E%20NO%5B%22%E7%AD%89%E5%BE%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回避比检测保守：拒绝进入不安全区，于是环不会形成。它要求<strong>事先知道最大需求</strong>，这在编译器已知的内核内部资源上偶尔成立，在用户随便 <code>malloc</code> 的世界里几乎不成立。因此通用 Unix 不以银行家为文件描述符的日常策略，教材用它说明「安全状态」与「死锁」不是同一集合。</p><p>与<a href="/cs/scheduling-metrics">调度</a>的关系：被银行家挡住的线程是阻塞，CPU 可以给别人；它等的是资源安全，不是 I/O 完成。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称 Linux 内核用银行家分配页框。不把死锁检测（跑时找环）与回避混成一步。最大需求若说谎，安全证明作废。也不处理资源种类动态增减。</p><p>多实例资源用矩阵；单实例时安全检查退化为避免图中出现环的预演，仍要配额。</p><p>后课默认：四条件之外还有「安全序列」这条回避路。操作系统作为课程要从同步回到<strong>地址空间长什么样</strong>——下一课布局，页表硬件仍用<a href="/cs/paging-vm">分页</a>，不重导。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>安全 = 存在做完次序；银行家只进入安全状态。</li><li>不安全未必已死锁；需要事先配额。</li><li>通用 OS 很少对用户内存跑银行家；概念仍要。</li><li>出处：Dijkstra 银行家算法；Habermann, <em>CACM</em> 1969；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const g=i(h,[["render",m]]);export{k as __pageData,g as default};
